pub fn table(module: &str) -> &'static [(u16, &'static str)] {
    match module {
        "KERNEL" => KERNEL,
        "USER" => USER,
        "GDI" => GDI,
        "MMSYSTEM" => MMSYSTEM,
        _ => &[],
    }
}

/// Name (uppercase, as in the NE module) of function `ordinal` in `module`.
pub fn name_of(module: &str, ordinal: u16) -> Option<&'static str> {
    table(module).iter().find(|(o, _)| *o == ordinal).map(|(_, n)| *n)
}
